#!/usr/bin/env python3
"""Script d'installation : extrait le module vectorization depuis un ZIP integre."""

import base64
import zipfile
import io
from pathlib import Path

PROJECT_ROOT = Path(r"C:\Users\dell\Desktop\Projet python - RAG\rag")

# ZIP integre en base64
ZIP_DATA = """"""

def install():
    print("=" * 50)
    print("INSTALLATION DU MODULE VECTORIZATION")
    print("=" * 50)
    print()

    # Decoder et extraire
    zip_bytes = base64.b64decode(ZIP_DATA)
    zf = zipfile.ZipFile(io.BytesIO(zip_bytes))

    for name in zf.namelist():
        content = zf.read(name)
        target = PROJECT_ROOT / name
        target.parent.mkdir(parents=True, exist_ok=True)
        with open(target, "wb") as fh:
            fh.write(content)
        print(f"  {name}")

    # Creer les dossiers supplementaires
    (PROJECT_ROOT / "data" / "vector_store").mkdir(parents=True, exist_ok=True)
    (PROJECT_ROOT / "vectorization" / "tests").mkdir(parents=True, exist_ok=True)

    print()
    print("=" * 50)
    print("INSTALLATION TERMINEE")
    print("=" * 50)
    print()
    print("Prochaines etapes :")
    print("  1. Verifier que chunks.jsonl existe dans data/output/")
    print("  2. python vectorization/scripts/build_index.py")
    print("  3. python vectorization/scripts/search.py \"votre question\"")
    print("  4. python vectorization/scripts/query.py \"votre question\"")


if __name__ == "__main__":
    install()